from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
styles=[('01-warm-rpg','Hearthside','TOP-DOWN RPG','#e8d8b6','#684d3c'),('02-isometric','Little Workplace','ISOMETRIC 2:1','#dceee7','#426861'),('03-office-tower','Office Tower','SIDE ELEVATION','#e3d8ca','#674b3f'),('04-pocket-office','Pocket Office','FOUR-COLOR HANDHELD','#c9d598','#354d32'),('05-neon-shift','Neon Shift','NIGHT OPERATIONS','#15102b','#a06abe'),('06-chibi-club','Chibi Work Club','PASTEL CHARACTER STUDIO','#f9e6ef','#a57994'),('07-office-95','Office 95','DESKTOP WINDOWS','#168782','#4a4a4a'),('08-focus-panel','Agent / Office','DARK IDE PANEL','#191e24','#46545a')]
for i,(folder,title,subtitle,bg,edge) in enumerate(styles):
 # Each page owns its rendering code and selects its own spatial arrangement.
 script=r'''const cn=document.querySelector('canvas'),ctx=cn.getContext('2d');ctx.imageSmoothingEnabled=false;const names=['desk-0','desk-1','desk-2','manager-desk','working-0','working-1','working-2','working-3','away-0','phone-0','phone-1','sleeping-0','sleeping-1','floor','wall','window','plant','door','coffee'];let img={};names.forEach(n=>{img[n]=new Image;img[n].src='sprites/'+n+'.png'});function I(n,x,y,w,h){if(img[n].complete&&img[n].naturalWidth)ctx.drawImage(img[n],Math.round(x),Math.round(y),w,h)}function R(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}function T(s,x,y,n=15,c=EDGE,align='left'){ctx.fillStyle=c;ctx.font=`bold ${n}px monospace`;ctx.textAlign=align;ctx.fillText(s,x,y)}
function station(x,y,state,k,t,boss=false,scale=2){let f=state==='working'?Math.floor(t/120)%4:state==='away'?0:Math.floor(t/500)%2;I(state+'-'+f,x-48*scale/2,y-46*scale,48*scale,48*scale);I(boss?'manager-desk':'desk-'+k,x-(boss?64:48)*scale/2,y-12*scale,(boss?64:48)*scale,(boss?48:40)*scale);T(state.toUpperCase(),x,y+35*scale,11,EDGE,'center');if(boss)T('★ ORCHESTRATOR',x,y-53*scale,12,EDGE,'center')}
function room(x,y,cols,rows,name,states,solo,t){let cell=150, w=cols*cell+80,h=rows*145+210;R(x+7,y+8,w,h,EDGE);R(x,y,w,h,'#eee5d5');for(let yy=y+48;yy<y+h-15;yy+=32)for(let xx=x+8;xx<x+w-15;xx+=32)I('floor',xx,yy,32,32);for(let xx=x+8;xx<x+w-15;xx+=32)I('wall',xx,y+8,32,32);I('window',x+25,y+8,32,32);I('window',x+w-60,y+8,32,32);I('plant',x+10,y+h-45,32,32);I('door',x+w-47,y+h-43,32,32);I('coffee',x+w-50,y+58,32,32);T(name,x+w/2,y+31,14,EDGE,'center');if(solo){station(x+w/2,y+135,'phone',2,t,false,2);return}R(x+w/2-90,y+55,180,115,'#c8ad91');station(x+w/2,y+135,states.length>2?'working':'sleeping',0,t,true,2);states.forEach((s,i)=>station(x+115+(i%cols)*cell,y+270+Math.floor(i/cols)*145,s,(i+1)%3,t,false,2))}
function iso(ox,oy,cols,rows,name,states,solo,t){let W=cols*2+1,H=rows*2+3;function p(u,v){return [ox+(u-v)*50,oy+(u+v)*25]}for(let u=0;u<W;u++)for(let v=0;v<H;v++){let [x,y]=p(u,v);I('floor',x-48,y,96,48)}let a=p(0,0),b=p(W,0),d=p(0,H);ctx.fillStyle='#8bb7a9';ctx.beginPath();ctx.moveTo(d[0],d[1]);ctx.lineTo(d[0],d[1]-48);ctx.lineTo(a[0],a[1]-48);ctx.lineTo(b[0],b[1]-48);ctx.lineTo(b[0],b[1]);ctx.lineTo(a[0],a[1]);ctx.closePath();ctx.fill();I('window',a[0]+35,a[1]-48,32,32);I('plant',d[0]+12,d[1]-30,32,32);T(name,a[0],a[1]-60,15,EDGE,'center');let agents=solo?[[1,1,'phone',2,false]]:[[Math.floor(W/2),0,'working',0,true],...states.map((s,i)=>[1+(i%cols)*2,2+Math.floor(i/cols)*2,s,(i+1)%3,false])];agents.sort((a,b)=>a[0]+a[1]-b[0]-b[1]);agents.forEach(([u,v,s,k,b])=>{let [x,y]=p(u,v);station(x,y+35,s,k,t,b,2)})}
function tower(x,base,cols,levels,name,states,solo,t){let w=cols*140+70,h=levels*155;R(x-6,base-h-12,w+12,h+12,EDGE);R(x,base-h,w,h,'#ead8c5');for(let f=0;f<levels;f++){let y=base-h+f*155;for(let xx=x;xx<x+w;xx+=32)I('wall',xx,y,32,32);I('window',x+12,y+25,48,48);I('plant',x+w-48,y+95,32,32);R(x,y+145,w,10,EDGE)}I('door',x+w-50,base-60,48,48);T(name,x+w/2,base-h-24,15,EDGE,'center');if(solo){station(x+w/2,base-62,'phone',2,t,false,2);return}station(x+w/2,base-h+105,'working',0,t,true,2);states.forEach((s,i)=>station(x+95+(i%cols)*140,base-h+(1+Math.floor(i/cols))*155+100,s,(i+1)%3,t,false,2))}
function win(x,y,cols,rows,name,states,solo,t){let w=cols*150+80,h=rows*145+270;R(x+8,y+8,w,h,'#333');R(x,y,w,h,'#c6c6c6');R(x+4,y+4,w-8,26,'#000080');T(name+' - OFFICE.EXE',x+12,y+23,13,'white');T('×',x+w-20,y+23,17,'white');T('File   Edit   View   Help',x+12,y+48,12,'#222');room(x+8,y+55,cols,rows,'',states,solo,t);R(x+5,y+h-22,w-10,18,'#aaa');T('Ready  |  '+(solo?'1 agent':(states.length+1)+' agents'),x+12,y+h-8,11,'#222')}
function frame(t){R(0,0,1600,1000,BG);T(TITLE,50,55,30,EDGE);T(SUB,52,82,14,EDGE);LAYOUT;T('✚ CLAUDE     ▣ CODEX     ✦ ANTIGRAVITY',55,925,15,EDGE);T('WORKING  /  AWAY  /  PHONE  /  SLEEPING',55,952,13,EDGE);requestAnimationFrame(frame)}requestAnimationFrame(frame);'''
 layouts=["room(50,125,3,2,'ALPHA / 7',['working','away','phone','sleeping','working','phone'],false,t);room(650,125,2,1,'BETA / 3',['away','phone'],false,t);room(1150,125,1,1,'SOLO / 1',[],true,t)","iso(410,180,3,2,'ALPHA / 7',['working','away','phone','sleeping','working','phone'],false,t);iso(1120,170,2,1,'BETA / 3',['away','sleeping'],false,t);iso(1300,570,1,1,'SOLO / 1',[],true,t)","tower(50,820,3,3,'ALPHA / 7',['working','away','phone','sleeping','working','phone'],false,t);tower(680,820,2,2,'BETA / 3',['away','phone'],false,t);tower(1190,820,1,1,'SOLO / 1',[],true,t)","room(70,130,3,2,'ALPHA / 7',['working','away','phone','sleeping','working','phone'],false,t);room(660,130,2,1,'BETA / 3',['away','phone'],false,t);room(1140,130,1,1,'SOLO / 1',[],true,t)","room(50,130,3,2,'NIGHT SHIFT / 7',['working','away','phone','sleeping','working','phone'],false,t);room(660,230,2,1,'NODE B / 3',['away','phone'],false,t);room(1150,380,1,1,'SOLO / 1',[],true,t)","room(70,160,3,2,'CLUB ALPHA / 7',['working','away','phone','sleeping','working','phone'],false,t);room(680,120,2,1,'CLUB BETA / 3',['away','phone'],false,t);room(1160,250,1,1,'SOLO / 1',[],true,t)","win(40,125,3,2,'ALPHA',['working','away','phone','sleeping','working','phone'],false,t);win(650,125,2,1,'BETA',['away','phone'],false,t);win(1140,125,1,1,'SOLO',[],true,t)","room(50,125,3,2,'ALPHA / 7',['working','away','phone','sleeping','working','phone'],false,t);room(660,125,2,1,'BETA / 3',['away','phone'],false,t);room(1150,125,1,1,'SOLO / 1',[],true,t)"]
 script=script.replace('BG',json.dumps(bg)).replace('EDGE',json.dumps(edge)).replace('TITLE',json.dumps(title)).replace('SUB',json.dumps(subtitle)).replace('LAYOUT',layouts[i])
 (root/folder/'index.html').write_text('<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+title+'</title><style>body{margin:0;background:'+bg+'}canvas{display:block;width:100%;height:auto;image-rendering:pixelated}</style><canvas width="1600" height="1000" aria-label="Animated pixel office"></canvas><script>'+script+'</script></html>')
